from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
import unittest

def _shift(worker: str, minutes: int) -> Shift:
    return Shift(worker, "mon", Span(540, 540 + minutes))

class TimesheetRowTests(unittest.TestCase):
    def test_name_count_and_hours(self):
        shifts = [_shift("Brisa", 240), _shift("Brisa", 180)]
        self.assertEqual(timesheet_rows(shifts), ["Brisa: 2 shifts, 7.0 hours"])

    def test_single_shift_is_singular(self):
        shifts = [_shift("Odell", 390)]
        self.assertEqual(timesheet_rows(shifts), ["Odell: 1 shift, 6.5 hours"])

    def test_busiest_first(self):
        shifts = [_shift("Odell", 390), _shift("Brisa", 540), _shift("Quill", 450)]
        expected = [
            "Brisa: 1 shift, 9.0 hours",
            "Quill: 1 shift, 7.5 hours",
            "Odell: 1 shift, 6.5 hours"
        ]
        self.assertEqual(timesheet_rows(shifts), expected)

    def test_ties_sorted_by_name(self):
        shifts = [_shift("Quill", 300), _shift("Brisa", 300)]
        expected = ["Brisa: 1 shift, 5.0 hours", "Quill: 1 shift, 5.0 hours"]
        self.assertEqual(timesheet_rows(shifts), expected)

    def test_rounds_half_up(self):
        # 9 hours 15 minutes is exactly 9.25 hours, which rounds up to 9.3
        shifts = [_shift("Brisa", 555)]
        self.assertEqual(timesheet_rows(shifts), ["Brisa: 1 shift, 9.3 hours"])

    def test_hours_to_one_decimal(self):
        shifts = [_shift("Brisa", 100)]
        self.assertEqual(timesheet_rows(shifts), ["Brisa: 1 shift, 1.7 hours"])

    def test_no_shifts_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker_raises(self):
        for worker in ("", "   "):
            with self.subTest(worker=worker):
                with self.assertRaises(ValueError):
                    timesheet_rows([_shift(worker, 60)])
